eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   PORTFOLIO_ITEMS: () => (/* binding */ PORTFOLIO_ITEMS),\n/* harmony export */   PORTFOLIO_PROJECTS: () => (/* binding */ PORTFOLIO_PROJECTS),\n/* harmony export */   getAllProjects: () => (/* binding */ getAllProjects),\n/* harmony export */   getCategories: () => (/* binding */ getCategories),\n/* harmony export */   getProjectBySlug: () => (/* binding */ getProjectBySlug),\n/* harmony export */   getRelatedProjects: () => (/* binding */ getRelatedProjects)\n/* harmony export */ });\n// Structured data for Portfolio / Selected Works.\n// To add a new project, simply add a new object to the PORTFOLIO_PROJECTS array.\nconst PORTFOLIO_PROJECTS = [\n    {\n        id: \"ekaprint-bali\",\n        slug: \"ekaprint-bali\",\n        title: \"Ekaprint Bali Integrated Management System\",\n        subtitle: \"Custom Enterprise Operations, POS & Printing Production Platform\",\n        type: \"Enterprise System\",\n        category: \"Printing ERP System\",\n        tags: [\n            \"Enterprise System\",\n            \"ERP\",\n            \"Printing ERP System\"\n        ],\n        client: \"Ekaprint Bali\",\n        year: \"2025\",\n        image: \"/assets/portfolio/ekaprint-order.png\",\n        bannerImage: \"/assets/portfolio/ekaprint-order.png\",\n        imageAlt: \"Ekaprint Bali Integrated System\",\n        ctaLabel: \"View Case Study\",\n        ctaHref: \"/portfolio/ekaprint-bali\",\n        ctaId: \"btn-ekaprint-bali\",\n        desc: \"Tailored web platform integrating POS, custom printing production workflows, HR, biometric fingerprint attendance, queue management, and financial analytics.\",\n        fullDesc: \"Ekaprint Bali is a leading commercial printing enterprise requiring a highly versatile operational system tailored to their unique business processes. EXP Digital Solution designed and delivered a unified, web-based management platform integrating Point-of-Sale (POS) order processing, specialized printing production workflows, HR management, biometric fingerprint attendance tracking, customer queue management, and real-time financial reporting into a single seamless ecosystem.\",\n        challenge: \"Ekaprint Bali faced significant operational bottlenecks with off-the-shelf ERP and POS software that could not accommodate their highly customized printing production workflows, unique pricing matrix, and specialized multi-department operations. Existing solutions were too rigid to integrate hardware like biometric fingerprint scanners and customer queue displays seamlessly.\",\n        solution: \"EXP Digital Solution engineered a flexible, bespoke enterprise web system built specifically around Ekaprint Bali's operational blueprint. The solution connects front-desk customer orders directly to the factory production floor, automates employee attendance tracking via integrated biometric fingerprint hardware, manages customer queue flow in real time, and synthesizes financial metrics into instant executive dashboards.\",\n        results: [\n            {\n                label: \"Operational Efficiency Boost\",\n                value: \"+55%\"\n            },\n            {\n                label: \"Administrative Time Saved\",\n                value: \"80+ hrs/mo\"\n            },\n            {\n                label: \"Cost & Overhead Reduction\",\n                value: \"35%\"\n            }\n        ],\n        keyModules: [\n            \"POS & Order Management System\",\n            \"Custom Printing Production Workflow\",\n            \"HR & Biometric Fingerprint Attendance Integration\",\n            \"Real-Time Customer Queue Management\",\n            \"Financial Reporting & Business Analytics\"\n        ],\n        gallery: [\n            \"/assets/portfolio/ekaprint-order.png\",\n            \"/assets/portfolio/ekaprint-fingerprint.png\"\n        ],\n        featured: true\n    },\n    {\n        id: \"gorila-gym-bali\",\n        slug: \"gorila-gym-bali\",\n        title: \"Gorila Gym Multi-Branch Management System\",\n        subtitle: \"Custom Fitness ERP, QR Member Attendance & Multi-Branch Operational Platform\",\n        type: \"Gym System\",\n        category: \"Gym System\",\n        tags: [\n            \"Gym System\",\n            \"ERP\"\n        ],\n        client: \"Gorila Gym Bali\",\n        year: \"2025\",\n        image: \"/assets/portfolio/gorila-pos.png\",\n        bannerImage: \"/assets/portfolio/gorila-pos.png\",\n        imageAlt: \"Gorila Gym Bali Management System\",\n        ctaLabel: \"View Case Study\",\n        ctaHref: \"/portfolio/gorila-gym-bali\",\n        ctaId: \"btn-gorila-gym-bali\",\n        desc: \"Integrated fitness management platform with instant QR code member attendance, multi-branch revenue monitoring, staff scheduling, POS sales, and executive financial reporting.\",\n        fullDesc: \"Gorila Gym Bali is a premier fitness chain in Bali requiring a high-flexibility digital ecosystem to scale its multi-branch operations. EXP Digital Solution designed and deployed a custom web-based gym management system that digitizes the entire member journey—replacing manual record-keeping with lightning-fast QR code check-ins, integrated POS sales, personal trainer management, and real-time multi-branch financial visibility.\",\n        challenge: \"Prior to our solution, Gorila Gym Bali operated manually using paper logs and fragmented spreadsheets for member registrations, daily attendance, and POS sales. As the gym expanded across multiple locations, management struggled to obtain real-time multi-branch revenue tracking, prevent membership check-in fraud, and consolidate financial reports efficiently.\",\n        solution: \"EXP Digital Solution delivered a highly flexible, tailor-made gym enterprise platform featuring instant QR Code scanning for member verification, integrated POS for supplement and membership sales, employee & personal trainer management, and an explicit multi-branch executive dashboard allowing the owner to monitor real-time growth, sales performance, and attendance trends for every branch independently.\",\n        results: [\n            {\n                label: \"Check-in Scan Speed\",\n                value: \"< 2 Seconds\"\n            },\n            {\n                label: \"Multi-Branch Growth Visibility\",\n                value: \"Real-Time 24/7\"\n            },\n            {\n                label: \"Operational Fraud Reduction\",\n                value: \"100%\"\n            }\n        ],\n        keyModules: [\n            \"QR Code Member Attendance & Scan System\",\n            \"Explicit Multi-Branch Executive Monitoring\",\n            \"Integrated Gym POS & Membership Sales\",\n            \"Employee & Personal Trainer Management\",\n            \"Multi-Location Financial Reporting & Analytics\"\n        ],\n        gallery: [\n            \"/assets/portfolio/gorila-pos.png\",\n            \"/assets/portfolio/gorila-implementation.jpeg\"\n        ],\n        featured: true\n    },\n    {\n        id: \"sparco-gym\",\n        slug: \"sparco-gym\",\n        title: \"Sparco Gym Dedicated Management System\",\n        subtitle: \"Custom Private Fitness ERP, QR Check-in & PT Scheduling Platform\",\n        type: \"Gym System\",\n        category: \"Gym System\",\n        tags: [\n            \"Gym System\",\n            \"ERP\"\n        ],\n        client: \"Sparco Gym\",\n        year: \"2024\",\n        image: \"/assets/portfolio/sparco-trainer-schedule.png\",\n        bannerImage: \"/assets/portfolio/sparco-trainer-schedule.png\",\n        imageAlt: \"Sparco Gym Management System\",\n        ctaLabel: \"View Case Study\",\n        ctaHref: \"/portfolio/sparco-gym\",\n        ctaId: \"btn-sparco-gym\",\n        desc: \"Dedicated fitness platform with instant QR member check-in, personal trainer scheduling, member management, and private financial reporting.\",\n        fullDesc: \"Sparco Gym sought a private, fully flexible management platform after experiencing severe frustrations with expensive third-party SaaS software. EXP Digital Solution engineered a dedicated web-based fitness ERP system that gives Sparco Gym 100% data ownership, custom flexibility, instant QR code member check-ins, automated Personal Trainer (PT) scheduling, and comprehensive financial reporting without ongoing vendor lock-in.\",\n        challenge: \"Sparco Gym previously relied on a third-party SaaS vendor that suffered from dangerously slow customer support response times during critical software outages. Furthermore, gym management had grave data privacy concerns regarding storing proprietary member and financial records on vendor cloud servers, compounded by high subscription costs and rigid feature limitations.\",\n        solution: \"EXP Digital Solution replaced their vendor lock-in with a custom, privately-hosted fitness system built specifically around Sparco Gym's operational needs. The new platform features instant QR Code member attendance scanning, an intuitive Personal Trainer (PT) session scheduler, comprehensive member lifecycle management, and verified financial reporting—delivering total data control, zero vendor dependency, and dramatic cost savings.\",\n        results: [\n            {\n                label: \"Data Ownership & Control\",\n                value: \"100% Private\"\n            },\n            {\n                label: \"Recurring Software Costs\",\n                value: \"-60% Saved\"\n            },\n            {\n                label: \"Vendor Response Lag\",\n                value: \"Eliminated\"\n            }\n        ],\n        keyModules: [\n            \"QR Code Member Attendance & Scan System\",\n            \"Personal Trainer (PT) Session Scheduler\",\n            \"Member Lifecycle Management\",\n            \"Private Financial Reporting & Analytics\",\n            \"Custom POS & Operational Dashboard\"\n        ],\n        gallery: [\n            \"/assets/portfolio/sparco-trainer-schedule.png\"\n        ],\n        featured: true\n    },\n    {\n        id: \"biantaradiva-photo\",\n        slug: \"biantaradiva-photo\",\n        title: \"Biantaradiva Photo Global Portfolio & Gallery CMS\",\n        subtitle: \"Aesthetic Portfolio Web App, Custom Gallery CMS & Web Analytics Platform\",\n        type: \"Photography Platform\",\n        category: \"Portfolio Website\",\n        tags: [\n            \"Portfolio Website\",\n            \"Web Application\",\n            \"Content Management System\",\n            \"Analytics\"\n        ],\n        client: \"Biantaradiva Photo\",\n        year: \"2025\",\n        image: \"/assets/portfolio/biantara-ss.png\",\n        bannerImage: \"/assets/portfolio/biantara-ss.png\",\n        imageAlt: \"Biantaradiva Photo Showcase & Dashboard\",\n        ctaLabel: \"View Case Study\",\n        ctaHref: \"/portfolio/biantaradiva-photo\",\n        ctaId: \"btn-biantaradiva-photo\",\n        desc: \"A bespoke, aesthetic web platform engineered to elevate a Bali-based photographer to a global audience—complete with an admin dashboard for gallery management and visitor analytics.\",\n        fullDesc: \"Biantaradiva Photo is a distinguished photographer based in Bali dedicated to capturing artistic visuals and timeless moments. To expand beyond local boundaries and showcase their expertise, portfolio, and years of experience to international clients, EXP Digital Solution engineered an aesthetic, high-performance web platform. Built to mirror Biantaradiva Photo's artistic identity, the platform features a stunning public showcase alongside a powerful custom admin dashboard for managing photo galleries, updating portfolio items, and tracking global visitor analytics in real time.\",\n        challenge: \"Biantaradiva Photo needed to establish an international digital presence that reflected their unique artistic standards. Standard portfolio platforms lacked the bespoke visual elegance required, offered limited branding flexibility, and failed to provide native visitor tracking or seamless gallery management tailored to professional photography workflows.\",\n        solution: \"EXP Digital Solution crafted a tailored, high-performance web experience with fluid visual presentation and optimized high-resolution image delivery. We integrated a dedicated client dashboard allowing Biantaradiva Photo to curate galleries, organize specialized service offerings, and analyze audience traffic demographics from across the globe in real time.\",\n        results: [\n            {\n                label: \"Global Web Visibility\",\n                value: \"International Reach\"\n            },\n            {\n                label: \"Gallery Upload & Workflow Speed\",\n                value: \"< 3 Mins\"\n            },\n            {\n                label: \"Audience Engagement Increase\",\n                value: \"+80%\"\n            }\n        ],\n        keyModules: [\n            \"Aesthetic High-Resolution Portfolio & Gallery Showcase\",\n            \"Custom Admin Dashboard for Gallery & Portfolio Management\",\n            \"Real-Time Web Visitor Tracking & Traffic Analytics\",\n            \"Global SEO Optimization & Fast Image Delivery Network\",\n            \"Services, Experience & Client Booking Inquiry Portal\"\n        ],\n        gallery: [\n            \"/assets/portfolio/biantara-ss.png\",\n            \"/assets/portfolio/biantara-ss2.png\"\n        ],\n        featured: true\n    },\n    {\n        id: \"stikes-bina-usada-bali\",\n        slug: \"stikes-bina-usada-bali\",\n        title: \"STIKES Bina Usada Bali Institutional Web Portal & Internal Systems\",\n        subtitle: \"Modern Educational Portal, Internal Room Booking ERP & Multi-System Maintenance Platform\",\n        type: \"Educational System\",\n        category: \"Institutional Platform\",\n        tags: [\n            \"Education\",\n            \"Institutional Web Portal\",\n            \"Internal Systems\",\n            \"System Maintenance\"\n        ],\n        client: \"STIKES Bina Usada Bali\",\n        year: \"2023\",\n        image: \"/assets/portfolio/stikes-landing.png\",\n        bannerImage: \"/assets/portfolio/stikes-landing.png\",\n        imageAlt: \"STIKES Bina Usada Bali Web Portal\",\n        ctaLabel: \"View Case Study\",\n        ctaHref: \"/portfolio/stikes-bina-usada-bali\",\n        ctaId: \"btn-stikes-bina-usada-bali\",\n        desc: \"A comprehensive digital transformation for a premier Nursing & Midwifery institute in Bali—featuring a manageable modern landing portal, internal facility booking systems, and ongoing multi-system maintenance.\",\n        fullDesc: \"STIKES Bina Usada Bali is a distinguished higher education institute dedicated to Nursing and Midwifery in Bali. Facing severe delays, high costs, and poor responsiveness from their previous software vendor, STIKES Bina Usada partnered with EXP Digital Solution for a complete digital overhaul. We developed a highly engaging, easily manageable institutional web portal, built custom internal operation systems (including facility & room reservation workflows), and provided dedicated maintenance and administration for their existing sub-systems such as Open Journal Systems (OJS) and the digital library.\",\n        challenge: \"The institution suffered from slow response times, poor communication, and excessive maintenance fees under their previous vendor. Furthermore, their existing digital presence lacked modern design flexibility, while campus administrative processes—such as facility and room bookings—were handled manually through fragmented paperwork.\",\n        solution: \"EXP Digital Solution replaced vendor friction with a responsive, client-first partnership model. We engineered a fast, manageable modern landing page allowing staff to easily publish academic news, built a centralized internal room and facility booking system, and took over end-to-end maintenance for key academic infrastructure including OJS journal portals and digital library systems.\",\n        results: [\n            {\n                label: \"Vendor Support Response Time\",\n                value: \"< 15 Mins\"\n            },\n            {\n                label: \"Facility Booking Efficiency\",\n                value: \"+90%\"\n            },\n            {\n                label: \"IT Operational Cost Reduction\",\n                value: \"45%\"\n            }\n        ],\n        keyModules: [\n            \"Manageable Modern Institutional Web Portal\",\n            \"Internal Campus Facility & Room Reservation System\",\n            \"Open Journal Systems (OJS) Management & Maintenance\",\n            \"Digital Library & Sub-system Integration\",\n            \"24/7 Dedicated Technical Support & Server Maintenance\"\n        ],\n        gallery: [\n            \"/assets/portfolio/stikes-landing.png\"\n        ],\n        featured: true\n    },\n    {\n        id: \"packaging-bali\",\n        slug: \"packaging-bali\",\n        title: \"Packaging Bali Digital Product Showcase & High-Conversion Ad Web Platform\",\n        subtitle: \"Custom B2B Packaging Web Catalog, 80% Content Management CMS & Ads-Optimized Platform\",\n        type: \"B2B Packaging Platform\",\n        category: \"Product Showcase & Ads Platform\",\n        tags: [\n            \"B2B E-Commerce\",\n            \"Packaging\",\n            \"Product Showcase\",\n            \"CMS Dashboard\",\n            \"Digital Marketing\"\n        ],\n        client: \"Packaging Bali\",\n        year: \"2026\",\n        image: \"/assets/portfolio/packagingbali-home.png\",\n        bannerImage: \"/assets/portfolio/packagingbali-home.png\",\n        imageAlt: \"Packaging Bali Product Showcase & CMS Dashboard\",\n        ctaLabel: \"View Case Study\",\n        ctaHref: \"/portfolio/packaging-bali\",\n        ctaId: \"btn-packaging-bali\",\n        desc: \"A high-conversion digital product catalog and corporate web platform backed by a custom CMS dashboard controlling 80%+ of the site's content, designed to drive targeted digital advertising campaigns.\",\n        fullDesc: \"Packaging Bali is a leading commercial packaging vendor providing high-quality packaging solutions for businesses across Bali and beyond. To scale their reach through targeted digital advertising (Ads campaigns), Packaging Bali partnered with EXP Digital Solution to build a conversion-ready web platform. We designed and engineered a modern, high-speed digital experience that showcases Packaging Bali's corporate vision and mission alongside an interactive product catalog. Furthermore, we equipped Packaging Bali with a powerful custom admin dashboard functioning as an intuitive Content Management System (CMS)—empowering their internal team to independently manage over 80% of the website's content, images, and product listings in real time.\",\n        challenge: \"Packaging Bali planned to launch aggressive digital advertising campaigns but lacked a structured, conversion-optimized online presence. Their goal was to move beyond traditional offline sales by providing prospective commercial buyers with a clear view of their brand philosophy, sustainable packaging commitment, and granular product specifications, while requiring total control to update product listings and promotional copy internally without developer dependency.\",\n        solution: \"EXP Digital Solution designed an ads-optimized web platform structured specifically for high-conversion buyer journeys. The site features an engaging corporate Vision & Mission presentation, detailed packaging product categorizations with specification breakdowns, and seamless lead generation touchpoints. To ensure maximum operational agility, we developed a custom CMS dashboard empowering the client to control over 80% of the web content—including updating product offerings, vision statements, and promotional banners on demand.\",\n        results: [\n            {\n                label: \"Content Managed via CMS\",\n                value: \"80%+ Site Control\"\n            },\n            {\n                label: \"Ad Campaign Conversion Rate\",\n                value: \"+65% Increase\"\n            },\n            {\n                label: \"Product Catalog Engagement\",\n                value: \"3.5x Higher\"\n            }\n        ],\n        keyModules: [\n            \"Custom CMS Dashboard (Manages 80%+ of Website Content)\",\n            \"High-Conversion Digital Packaging Product Catalog\",\n            \"Corporate Vision, Mission & Brand Value Showcase\",\n            \"Ads Landing Page Optimization & Speed Architecture\",\n            \"Granular Product Specifications & Direct Lead Gateway\"\n        ],\n        gallery: [\n            \"/assets/portfolio/packagingbali-home.png\",\n            \"/assets/portfolio/packagingbali-product.png\"\n        ],\n        featured: true\n    }\n];\n// Compatibility layer for existing components\nconst PORTFOLIO_ITEMS = PORTFOLIO_PROJECTS.map((project)=>({\n        image: project.image,\n        imageAlt: project.imageAlt,\n        ctaLabel: project.ctaLabel,\n        ctaHref: `/portfolio/${project.slug}`,\n        ctaId: project.ctaId,\n        type: project.type,\n        title: project.title,\n        desc: project.desc,\n        slug: project.slug\n    }));\n// Helper functions for easy querying\nfunction getAllProjects() {\n    return PORTFOLIO_PROJECTS;\n}\nfunction getProjectBySlug(slug) {\n    return PORTFOLIO_PROJECTS.find((p)=>p.slug === slug);\n}\nfunction getRelatedProjects(currentSlug, limit = 2) {\n    return PORTFOLIO_PROJECTS.filter((p)=>p.slug !== currentSlug).slice(0, limit);\n}\nfunction getCategories() {\n    const allTags = PORTFOLIO_PROJECTS.flatMap((p)=>[\n            p.category,\n            p.type,\n            ...p.tags || []\n        ]).filter(Boolean);\n    return [\n        \"All\",\n        ...Array.from(new Set(allTags))\n    ];\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/portfolio.js\n");

